// The committed layout vectors are generated by scripts/gen_bus_layout_vectors.py
// from the specification, independently of any client. The C
// (src/tests/test_bus_layout.c) and Rust (rust/aimee-bus/src/layout.rs) clients
// are held to the same table, so the three agree through it rather than by
// reading each other. Checked in both directions: every row must match a Go
// value, and every Go value listed here must have a row.
const layoutPath = "../../src/tests/fixtures/bus/layout_vectors.tsv"

