func TestLayoutVectors(t *testing.T) {
	f, err := os.Open(layoutPath)
	if err != nil {
		t.Fatalf("open layout vectors: %v", err)
	}
	defer f.Close()
	want := goLayout()
	seen := map[string]bool{}
	sc := bufio.NewScanner(f)
	rows := 0
	for sc.Scan() {
		line := sc.Text()
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		name, text, ok := strings.Cut(line, "\t")
		if !ok {
			t.Fatalf("malformed row: %q", line)
		}
		value, err := strconv.ParseUint(text, 0, 64)
		if err != nil {
			t.Fatalf("%s: value %q: %v", name, text, err)
		}
		rows++
		got, known := want[name]
		if !known {
			t.Errorf("row %s has no Go counterpart (add one to layout_test.go)", name)
			continue
		}
		if seen[name] {
			t.Errorf("duplicate row %s", name)
		}
		seen[name] = true
		if got != value {
			t.Errorf("%s: table %d, Go %d", name, value, got)
		}
	}
	if err := sc.Err(); err != nil {
		t.Fatal(err)
	}
	for name := range want {
		if !seen[name] {
			t.Errorf("Go value %s is missing from the table", name)
		}
	}
	if rows == 0 {
		t.Fatal("no layout rows checked")
	}
}

// The AMOD offsets are also checked behaviourally: an encoded message must
// carry each field at the table's offset.
func TestModuleMessageFieldsAtLayoutOffsets(t *testing.T) {
	m := ModuleMessage{Operation: ModuleOpResult, Status: ModuleStatusInternal, StageID: 0x51525354,
		BodyLen: 0, DeadlineNS: 0x7172737475767778, TraceID: 0x8182838485868788}
	var b [ModuleMessageHeaderLen]byte
	if _, err := m.Encode(b[:]); err != nil {
		t.Fatal(err)
	}
	got, err := DecodeModuleMessage(b[:])
	if err != nil || got != m {
		t.Fatalf("round trip: %+v %v", got, err)
	}
	if b[amodOffStageID] != 0x54 || b[amodOffDeadline] != 0x78 || b[amodOffTraceID] != 0x88 ||
		b[amodOffStatus] != byte(ModuleStatusInternal) || b[amodOffOperation] != byte(ModuleOpResult) {
		t.Fatalf("fields are not where the layout says: % x", b)
	}
}
